/**
 * Automation lifecycle status
 */
export const SiteAutomationStatus = { DRAFT: 'draft', ACTIVE: 'active' } as const;

/**
 * Automation lifecycle status
 */
export type SiteAutomationStatus = typeof SiteAutomationStatus[keyof typeof SiteAutomationStatus];

/**
 * One node in an automation's ordered, linear sequence. A flat shape: email
 * steps carry subject/body, wait steps carry seconds.
 */
export type SiteAutomationStep = {
  /**
   * Step kind
   */
  type: SiteAutomationStepType;
  /**
   * Email subject (email steps)
   */
  subject?: string;
  /**
   * Email body as HTML (email steps), or the Liquid JSON request body (HTTP steps: Contact bindings only, strings JSON-escaped, up to 64 KiB, must render to valid JSON)
   */
  body?: string;
  /**
   * The editor's JSON document an email step's body was built from, an opaque object checked by the
   * server. Write it instead of `body` (both is a 422): the server renders the body from it in the
   * same save, and a document that cannot be rendered refuses the whole save, naming the step.
   * Writing only a body clears the step's document.
   */
  doc?: {
    [key: string]: unknown;
  };
  /**
   * Version of the editor that rendered the document (email steps, read only)
   */
  editorVersion?: string;
  /**
   * Delay before the next step, in seconds (wait steps)
   */
  seconds?: number;
  /**
   * Tag name to apply or remove (apply_tag and remove_tag steps)
   */
  tag?: string;
  /**
   * Step id (HTTP steps). Assigned on save; send it back on edit so the step keeps its secrets.
   */
  id?: string;
  /**
   * Hook URL to POST to (HTTP steps). A secret: never returned. Omit it when editing to keep the stored URL. Up to 2 KiB, http or https.
   */
  url?: string;
  /**
   * Up to 5 request headers (HTTP steps). On read, only the names are returned.
   */
  headers?: Array<SiteAutomationHttpHeader>;
  /**
   * Signing secret (HTTP steps): when set, the request is signed with Standard Webhooks. Never returned. Omit it when editing to keep the stored secret.
   */
  secret?: string;
  /**
   * Remove the signing secret on save (HTTP steps)
   */
  clearSecret?: boolean;
  /**
   * Whether a signing secret is stored (HTTP steps, read only)
   */
  hasSecret?: boolean;
};

/**
 * Kind of automation step
 */
export const SiteAutomationStepType = {
  EMAIL: 'email',
  WAIT: 'wait',
  APPLY_TAG: 'apply_tag',
  REMOVE_TAG: 'remove_tag',
  HTTP: 'http'
} as const;

/**
 * Kind of automation step
 */
export type SiteAutomationStepType = typeof SiteAutomationStepType[keyof typeof SiteAutomationStepType];

/**
 * The Workspace's Brand kit (ADR 0040): its colors, fonts, logo, button style and footer. It sets
 * the palette the editor offers and what an agent is told to use. Its values are written into a
 * message when the message is authored, so saving it never changes a message already written. A
 * Workspace that has not saved one has the defaults and `saved` false.
 */
export type SiteBrandKitResource = {
  /**
   * False until the Brand kit is first saved; the values are then the defaults
   */
  saved: boolean;
  /**
   * Brand color of buttons and links, `#rrggbb`
   */
  accentColor: string;
  /**
   * Color of text, `#rrggbb`
   */
  textColor: string;
  /**
   * Color of the message background, `#rrggbb`
   */
  backgroundColor: string;
  /**
   * Font of headings: a CSS font-family list of web-safe families
   */
  headingFont: string;
  /**
   * Font of body text: a CSS font-family list of web-safe families
   */
  bodyFont: string;
  /**
   * Address (http or https) of the logo image; empty for none
   */
  logoUrl: string;
  /**
   * Color of the text on a button, `#rrggbb`
   */
  buttonTextColor: string;
  /**
   * Corner radius of a button in pixels, 0 to 32
   */
  buttonRadius: number;
  /**
   * Plain text printed under the starter messages, at most 500 characters; empty for none
   */
  footerText: string;
  /**
   * When the Brand kit was last saved; absent while it is not saved
   */
  updatedAt?: Timestamp | null;
};

/**
 * A broadcast's per-link click figures, most clicked first
 */
export type SiteBroadcastLinkClicksList = {
  /**
   * One entry per clicked link
   */
  items: Array<SiteLinkClicks>;
};

/**
 * How far a sending broadcast has got. A broadcast limited by its Integration's Send
 * rate limit is paced: recipients go out at an even interval, so the estimate is
 * derived on the server from the last scheduled time and the recipients remaining.
 */
export type SiteBroadcastProgress = {
  /**
   * Recipients already decided: sent, skipped or failed
   */
  processedCount: number;
  /**
   * Recipients still waiting to be sent
   */
  remainingCount: number;
  /**
   * When the last remaining recipient is expected to be sent. Null when it is not
   * knowable: the broadcast is on hold, or it is not paced by a Send rate limit.
   */
  estimatedCompletionAt?: Timestamp | null;
};

/**
 * Broadcast resource used by the site UI
 */
export type SiteBroadcastResource = {
  /**
   * Unique identifier
   */
  id: EntityId;
  /**
   * Internal broadcast name
   */
  name: string;
  /**
   * Email subject line
   */
  subject: string;
  /**
   * Sender display name (defaults to the integration's)
   */
  fromName?: string | null;
  /**
   * Sender email address (defaults to the integration's)
   */
  fromEmail?: EmailAddress | null;
  /**
   * HTML body with Liquid merge tags
   */
  body: string;
  /**
   * The editor's JSON document the body was built from; null when the body was written as HTML
   */
  doc?: {
    [key: string]: unknown;
  } | null;
  /**
   * Version of the editor that rendered the document; null with it
   */
  editorVersion?: string | null;
  /**
   * Warnings of the lint over the stored content (ADR 0040); set on the response of a save, never blocks it
   */
  warnings?: Array<LintFinding>;
  /**
   * Derived plain-text body
   */
  bodyText: string;
  /**
   * Target segment; null means all active contacts
   */
  segmentId?: EntityId | null;
  /**
   * Sending integration; null means the workspace default
   */
  integrationId?: EntityId | null;
  /**
   * Lifecycle status
   */
  status: SiteBroadcastStatus;
  /**
   * Why sending is currently held, when it is: `workspace_suspended`,
   * `unverified_domain` or `no_integration`. A hold is reversible and not a failure:
   * the broadcast keeps its status and the remaining recipients send once it lifts.
   */
  holdReason?: string | null;
  /**
   * When the broadcast is scheduled to send
   */
  scheduledAt?: Timestamp | null;
  /**
   * When the broadcast finished sending
   */
  sentAt?: Timestamp | null;
  /**
   * Delivery counters
   */
  stats: SiteBroadcastStats;
  /**
   * Progress and ETA while the broadcast is sending; null otherwise. Returned by get and send only, never by the list
   */
  progress?: SiteBroadcastProgress | null;
  /**
   * When the broadcast was archived; null while it is kept. Only a sent or failed broadcast is archived.
   */
  archivedAt?: Timestamp | null;
  /**
   * Creation timestamp
   */
  createdAt: Timestamp;
  /**
   * Last update timestamp
   */
  updatedAt: Timestamp;
};

/**
 * Denormalized delivery counters for a broadcast
 */
export type SiteBroadcastStats = {
  /**
   * Number of recipients the broadcast targets
   */
  recipientsTotal: number;
  /**
   * Messages successfully handed to the provider
   */
  sentCount: number;
  /**
   * Recipients that opened the email
   */
  openedCount: number;
  /**
   * Recipients that clicked a link
   */
  clickedCount: number;
  /**
   * Recipients that unsubscribed via this broadcast
   */
  unsubscribedCount: number;
  /**
   * Messages that failed to send
   */
  failedCount: number;
  /**
   * Messages the provider reported delivered, read from the delivery result stamped on each message
   */
  deliveredCount: number;
  /**
   * Messages the provider reported bounced, read from the delivery result stamped on each message
   */
  bouncedCount: number;
  /**
   * Messages a recipient complained about, read from the delivery result stamped on each message
   */
  complainedCount: number;
  /**
   * Messages handed to the provider ÷ recipients targeted (0–1)
   */
  deliveryRate: number;
  /**
   * Unique opens ÷ messages sent (0–1)
   */
  openRate: number;
  /**
   * Unique clicks ÷ messages sent (0–1)
   */
  clickRate: number;
  /**
   * Unique clicks ÷ unique opens (0–1)
   */
  clickToOpenRate: number;
  /**
   * Unsubscribes ÷ messages sent (0–1)
   */
  unsubscribeRate: number;
  /**
   * Send failures ÷ recipients targeted (0–1)
   */
  failureRate: number;
};

