/**
 * Why an endpoint is off. A closed set: `owner` (a member turned it off), `gone` (the
 * receiver answered 410 Gone) and `persistent_failure` (deliveries failed for longer
 * than the window). Absent while the endpoint is enabled.
 */
export const SiteWebhookDisabledReason = {
  OWNER: 'owner',
  GONE: 'gone',
  PERSISTENT_FAILURE: 'persistent_failure'
} as const;

/**
 * Why an endpoint is off. A closed set: `owner` (a member turned it off), `gone` (the
 * receiver answered 410 Gone) and `persistent_failure` (deliveries failed for longer
 * than the window). Absent while the endpoint is enabled.
 */
export type SiteWebhookDisabledReason = typeof SiteWebhookDisabledReason[keyof typeof SiteWebhookDisabledReason];

/**
 * Webhook endpoint resource used by the site UI
 */
export type SiteWebhookEndpointResource = {
  /**
   * Unique identifier
   */
  id: EntityId;
  /**
   * Destination URL events are POSTed to
   */
  url: string;
  /**
   * HMAC signing secret (receivers verify the webhook-id, webhook-timestamp and webhook-signature headers, the Standard Webhooks scheme)
   */
  secret: string;
  /**
   * Event names this endpoint receives; empty means all events
   */
  eventTypes: Array<string>;
  /**
   * Whether the endpoint receives deliveries: true while it has no `disabledAt`
   */
  enabled: boolean;
  /**
   * When the endpoint was turned off; absent while it is enabled
   */
  disabledAt?: Timestamp;
  /**
   * Why the endpoint is off; present exactly when `disabledAt` is
   */
  disabledReason?: SiteWebhookDisabledReason;
  /**
   * Present while deliveries are failing; cleared by the next 2xx
   */
  failure?: SiteWebhookFailure;
  /**
   * Creation timestamp
   */
  createdAt: Timestamp;
  /**
   * Last update timestamp
   */
  updatedAt: Timestamp;
};

/**
 * Why a delivery to a webhook endpoint failed. A closed set: `timeout` (no answer in
 * time), `blocked_address` (the URL names an address this instance does not permit),
 * `http_status` (a non-2xx answer, see `status`) and `network` (any other transport
 * failure).
 */
export const SiteWebhookErrorKind = {
  TIMEOUT: 'timeout',
  BLOCKED_ADDRESS: 'blocked_address',
  HTTP_STATUS: 'http_status',
  NETWORK: 'network'
} as const;

/**
 * Why a delivery to a webhook endpoint failed. A closed set: `timeout` (no answer in
 * time), `blocked_address` (the URL names an address this instance does not permit),
 * `http_status` (a non-2xx answer, see `status`) and `network` (any other transport
 * failure).
 */
export type SiteWebhookErrorKind = typeof SiteWebhookErrorKind[keyof typeof SiteWebhookErrorKind];

/**
 * The failure state of an endpoint that is currently failing; absent while it is healthy.
 */
export type SiteWebhookFailure = {
  /**
   * Deliveries that failed in a row
   */
  consecutiveFailures: number;
  /**
   * When the current run of failures began
   */
  since: Timestamp;
  /**
   * When the latest delivery failed
   */
  lastFailureAt: Timestamp;
  /**
   * Kind of the latest failure
   */
  kind: SiteWebhookErrorKind;
  /**
   * HTTP status of the latest failure; present only for kind `http_status`
   */
  status?: number;
};

/**
 * What the receiver answered to a test delivery. The endpoint's failure state is not touched.
 */
export type SiteWebhookTestResult = {
  /**
   * Whether the receiver answered 2xx
   */
  delivered: boolean;
  /**
   * HTTP status the receiver answered, when it answered
   */
  status?: number;
  /**
   * Why the delivery failed; absent when delivered
   */
  kind?: SiteWebhookErrorKind;
};

/**
 * A Staff hold on the Workspace's outbound sending (ADR 0009), as the Workspace's
 * members see it. It is not a suspension: it is set from outside, carries its own
 * message, and lifts by itself at its expiry.
 */
export type SiteWorkspaceHold = {
  /**
   * The setter's key, unique per Workspace
   */
  key: string;
  /**
   * Machine reason code the setter gave
   */
  reasonCode: string;
  /**
   * The setter's message for the Owner, to show as given
   */
  message: string;
  /**
   * When the hold was set
   */
  since: Timestamp;
  /**
   * Where an Owner or Admin can resolve the hold, as the setter gave it; absent when none was given
   */
  actionUrl?: string | null;
};

/**
 * Workspace the current user belongs to
 */
export type SiteWorkspaceResource = {
  /**
   * The Workspace id: its short opaque public address and the route key for nested
   * workspace resources (ADR 0043)
   */
  id: WorkspaceId;
  /**
   * Display name
   */
  name: string;
  /**
   * Per-workspace collect write-key (x-collect-key) for the tracking snippet
   */
  collectKey: string;
  /**
   * Physical postal address printed in the marketing email footer (CAN-SPAM
   * 15 U.S.C. §7704(a)(5)). Empty until the workspace sets one.
   */
  postalAddress: string;
  /**
   * The authenticated User's role in this Workspace (from their Membership). It
   * rides the Workspace list so role-gated UI is known even while the Workspace's
   * own endpoints are withheld under a Two-factor requirement.
   */
  role: SiteMembershipRole;
  /**
   * When outbound sending was suspended (ADR 0007); absent while the workspace can
   * send. A suspension freezes every send surface but not login, reads or tracking.
   */
  suspendedAt?: Timestamp | null;
  /**
   * Why sending was suspended, shown to the owner; present only while suspended.
   */
  suspensionReason?: string | null;
  /**
   * Where to appeal a suspension by email (SPHERICON_SUPPORT_EMAIL); absent when the instance
   * configured none.
   */
  supportEmail?: string | null;
  /**
   * The public origin an AI agent connects to as `<mcpUrl>/mcp`: SPHERICON_MCP_URL when MCP has its
   * own host, otherwise the app origin.
   */
  mcpUrl: string;
  /**
   * The Staff holds active now, oldest key first; empty while nothing holds sending.
   * Any one freezes every send surface, like a suspension, but a lapsed hold is never
   * listed.
   */
  holds: Array<SiteWorkspaceHold>;
  /**
   * When an Owner or Admin switched on the Two-factor requirement (ADR 0020);
   * absent while every member may work without a Second factor.
   */
  secondFactorRequiredAt?: Timestamp | null;
  /**
   * When the authenticated User's grace under the Two-factor requirement ends:
   * 7 days after the later of the requirement's start and their Membership's
   * creation. Absent without a requirement or once the User has a Second factor.
   * After it, every request to this Workspace answers 403 with code
   * second_factor_required until the User enrolls one.
   */
  secondFactorGraceEndsAt?: Timestamp | null;
  /**
   * Whether the authenticated User may open the Account link: true only for an
   * Owner, and only on an installation configured for it.
   */
  accountLinkAvailable: boolean;
  /**
   * Creation timestamp
   */
  createdAt: Timestamp;
};

